class Solution {
  public int minimumOperations(int[][] grid) {
    int ops = 0;
    for (int j = 0; j < grid[0].length; j++) {
      for (int i = 1; i < grid.length; i++) {
        if (grid[i][j] <= grid[i - 1][j]) {
          int need = grid[i - 1][j] + 1;
          ops += need - grid[i][j];
          grid[i][j] = need;
        }
      }
    }
    return ops;
  }
}
